function TBL=cps22_manual_calculation_book(T,P,F,z,x,y,beta,L,V,Ps,gamma,srkV,residual,massFeed,massL,massV)
% Produces a traceable calculation register. Rows distinguish empirical basis,
% equations, assumptions, and accepted/failed status. This is not a design code.
ids={'MC-001';'MC-002';'MC-003';'MC-008';'MC-009';'MC-011';'MC-013';'MC-018';'MC-019';'MC-022';'MC-025';'MC-026';'MC-028';'MC-045';'MC-056'};
titles={'Unit conversion';'Composition normalization';'Feed component rates';'Lever-rule vapour fraction';'Phase total flows';'Component closure';'Mass closure';'Ethanol Psat';'Water Psat';'NRTL activity coefficients';'SRK vapour root';'SRK fugacity coefficients';'Fugacity residual acceptance';'Illustrative duty';'Cost correlation range'};
inputs={sprintf('F=%.6f kmol/h',F);sprintf('z=[%.6f %.6f]',z);sprintf('F=%.6f kmol/h',F);sprintf('z1=%.6f; x1=%.9f; y1=%.9f',z(1),x(1),y(1));sprintf('F=%.6f; beta=%.9f',F,beta);'Feed n=[50,50] kmol/h';sprintf('mFeed=%.6f kg/h',sum(massFeed));sprintf('T=%.9f K',T);sprintf('T=%.9f K',T);sprintf('x=[%.9f %.9f], T=%.6f K',x,T);sprintf('A=%.8f B=%.8f',srkV.A,srkV.B);sprintf('Z=%.9f',srkV.Z);sprintf('r=[%.9f %.9f]',residual);'Cp ethanol assumed=130 J/mol/K';'Vessel V=pi*D^2*L/4, D=0.5,L=2.0';};
eqs={'mol/s=kmol/h*1000/3600';'sum(z_i)=1';'n_i=F*z_i';'beta=(z-x)/(y-x)';'V=F beta; L=F(1-beta)';'n_i,F−n_i,L−n_i,V';'mass feed−mass outlets';'log10(Psat/bar)=A−B/(T+C)';'log10(Psat/bar)=A−B/(T+C)';'NRTL equation using tau=a+b/T';'SRK cubic; largest real Z>B';'SRK ln(phi_i) expression';'ln(y phi P/(x gamma Psat phi_sat Poynting))';'sum sensible and pure-fluid latent screens';'Compare V with correlation bounds'};
values={sprintf('%.9f mol/s',F*1000/3600);sprintf('%.9f',sum(z));sprintf('[%.6f %.6f] kmol/h',F*z);sprintf('%.9f',beta);sprintf('L=%.6f; V=%.6f kmol/h',L,V);'0.000000 kmol/h each';sprintf('%.9f kg/h closure',sum(massFeed)-sum(massL)-sum(massV));sprintf('%.6f bar',Ps(1)/1e5);sprintf('%.6f bar',Ps(2)/1e5);sprintf('gamma=[%.6f %.6f]',gamma);sprintf('Z=%.9f',srkV.Z);sprintf('phi=[%.8f %.8f]',srkV.phi);sprintf('max abs residual=%.9f; FAIL',max(abs(residual)));'664.643 kW scenario only; NOT accepted';'V=0.392699 m3; size-range pass only';};
units={'mol/s';'-';'kmol/h';'-';'kmol/h';'kmol/h';'kg/h';'bar';'bar';'-';'-';'-';'-';'kW';'m3'};
status={'CALCULATED';'PASS';'CALCULATED';'EMPIRICAL_REFERENCE';'EMPIRICAL_REFERENCE';'PASS_ARITHMETIC';'PASS_ARITHMETIC';'NIST_CORRELATION';'NIST_CORRELATION';'CANDIDATE_ONLY';'DIAGNOSTIC_ONLY';'DIAGNOSTIC_ONLY';'FAIL';'SCREEN_ONLY';'RANGE_ONLY_NOT_CAPEX'};
notes={'Assumed throughput';'Normalized input';'Assumed feed composition';'Tie-line interpolation, not NRTL-SRK';'Lever rule on measured tie-line';'No reaction or losses';'Balance closure by calculation';'NIST SRD 69; valid T range';'NIST SRD 69; valid T range';'Low-pressure candidate set';'No phase-stability test';'kij is diagnostic';'Acceptance tolerance 1e-6';'Assumed ethanol Cp and Watson water latent heat';'Pressure/material factor and installed cost not applied'};
TBL=table(ids,titles,inputs,eqs,values,units,status,notes,'VariableNames',{'CalcID','Calculation','InputsAndUnits','EquationOrMethod','Result','Units','Status','Limitations'});
end
